local FullerMaker = {}
local PRODUCTS = {
    iron_fuller = { name = "Železni fuller za utorjanje", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni fuller za utorjanje za kovace." },
    bronze_fuller = { name = "Bronast fuller za utorjanje", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast fuller za utorjanje za kovace." },
    silver_fuller = { name = "Srebrn fuller za utorjanje", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn fuller za utorjanje za kovace." },
    gilded_fuller = { name = "Pozlačen fuller za utorjanje", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen fuller za utorjanje za kovace." },
    jewel_set_fuller = { name = "Draguljast fuller za utorjanje", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast fuller za utorjanje za kovace." },
    royal_sovereign_fuller = { name = "Kraljevski suveren fuller za utorjanje", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren fuller za utorjanje z biseri za krono." },
}
local BUILDINGS = {
    fuller_workshop = { name = "Fuller delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    fuller_house = { name = "Fuller hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_fuller_atelier = { name = "Mojstrski fuller atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_fuller_palace = { name = "Suverena fuller palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
FullerMaker.ironStock=18; FullerMaker.bronzeStock=14; FullerMaker.woodStock=10; FullerMaker.leatherStock=8; FullerMaker.silverStock=8; FullerMaker.goldStock=6; FullerMaker.jewelStock=4; FullerMaker.pearlStock=4
FullerMaker.productStock = {}; FullerMaker.buildings = {}; FullerMaker.maker = nil; FullerMaker.activeMaking = {}; FullerMaker.totalProducts = 0; FullerMaker.dayTimer = 0
function FullerMaker.init() FullerMaker.ironStock=18; FullerMaker.bronzeStock=14; FullerMaker.woodStock=10; FullerMaker.leatherStock=8; FullerMaker.silverStock=8; FullerMaker.goldStock=6; FullerMaker.jewelStock=4; FullerMaker.pearlStock=4; FullerMaker.productStock={}; FullerMaker.buildings={}; FullerMaker.maker=nil; FullerMaker.activeMaking={}; FullerMaker.totalProducts=0; FullerMaker.dayTimer=0; print("[FullerMaker] Royal Fuller Maker System initialized (6 products, 4 buildings)") end
function FullerMaker.hireMaker(n,s) s=s or math.random(55,90); local c=570+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; FullerMaker.maker={name=n or ("Utorjar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Utorjar najet: %s (spretnost: %d)",FullerMaker.maker.name,s),"success") end; return true end
function FullerMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function FullerMaker.build(id) local ok,e=FullerMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(FullerMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function FullerMaker.getQualityBonus() local b=0; for _,bd in ipairs(FullerMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function FullerMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and FullerMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and FullerMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and FullerMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and FullerMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and FullerMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and FullerMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and FullerMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and FullerMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #FullerMaker.buildings==0 then return false,"Potrebna utorjalna delavnica" end; if not FullerMaker.maker then return false,"Potreben utorjar" end; return true end
function FullerMaker.make(pt,qty) qty=qty or 1; local ok,e=FullerMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then FullerMaker.ironStock=FullerMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then FullerMaker.bronzeStock=FullerMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then FullerMaker.woodStock=FullerMaker.woodStock-d.woodCost*qty end; if d.leatherCost then FullerMaker.leatherStock=FullerMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then FullerMaker.silverStock=FullerMaker.silverStock-d.silverCost*qty end; if d.goldCost then FullerMaker.goldStock=FullerMaker.goldStock-d.goldCost*qty end; if d.jewelCost then FullerMaker.jewelStock=FullerMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then FullerMaker.pearlStock=FullerMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if FullerMaker.maker then t=math.max(1,t-math.floor(FullerMaker.maker.skill/13)) end; table.insert(FullerMaker.activeMaking,{id="fuller_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function FullerMaker.completeMaking(m) local q=1.0+(FullerMaker.getQualityBonus()/100); if FullerMaker.maker then q=q+(FullerMaker.maker.skill/140) end; q=math.min(2.5,q); FullerMaker.productStock[m.productType]=(FullerMaker.productStock[m.productType] or 0)+m.quantity; FullerMaker.totalProducts=FullerMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if FullerMaker.maker then FullerMaker.maker.itemsMade=FullerMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then FullerMaker.maker.skill=math.min(100,FullerMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Fuller izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"fuller.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function FullerMaker.update(dt) if not _G.state then return end; FullerMaker.dayTimer=FullerMaker.dayTimer+dt; if FullerMaker.dayTimer>=30 then FullerMaker.dayTimer=0; for i=#FullerMaker.activeMaking,1,-1 do local m=FullerMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then FullerMaker.completeMaking(m); table.remove(FullerMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(FullerMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if FullerMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function FullerMaker.getStats() return {ironStock=FullerMaker.ironStock,bronzeStock=FullerMaker.bronzeStock,woodStock=FullerMaker.woodStock,leatherStock=FullerMaker.leatherStock,silverStock=FullerMaker.silverStock,goldStock=FullerMaker.goldStock,jewelStock=FullerMaker.jewelStock,pearlStock=FullerMaker.pearlStock,productStock=FullerMaker.productStock,numBuildings=#FullerMaker.buildings,hasMaker=FullerMaker.maker~=nil,makerName=FullerMaker.maker and FullerMaker.maker.name or "—",makerSkill=FullerMaker.maker and FullerMaker.maker.skill or 0,activeMaking=#FullerMaker.activeMaking,totalProducts=FullerMaker.totalProducts} end
return FullerMaker
